function progressEntry(item,stamps,at=now()){return {id:'step-'+hash([...item.sourceIds].sort().join('|')+'|'+JSON.stringify(stamps)),at,sourceTime:item.sourceTime,sourceTimes:item.sourceTimes,eventTime:item.eventTime,content:item.followup||item.content,sourceIds:[...item.sourceIds],sourceStamps:{...stamps},snapshot:clone(item)};}
